import json
from pathlib import Path
R=Path(__file__).resolve().parents[1]; E=R/'evidence'
def rd(n): return json.loads((E/(n+'.json')).read_text(encoding='utf-8'))
def wr(n,x): (R/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def redact(x):
 if isinstance(x,dict): return {k:redact(v) for k,v in x.items()}
 if isinstance(x,list): return [redact(v) for v in x]
 if isinstance(x,str): return x.replace('"[…','"[REDACTED')
 return x
def main():
 c,cs,links,near=map(rd,('cat','cands','comps','near'))
 c=redact(c)
 by={case:u for u in c['units'] for case in u['baselineCaseIds']}
 for x in links+near:
  if x['baselineCaseId'] in by: x['unitId']=by[x['baselineCaseId']]['unitId']
 c['counts'].update(candidateBaselineLinks=len(links),distinctCandidateBaselineCases=len({x['baselineCaseId'] for x in links}),nearbyScreenedLinks=len(near))
 wr('BEHAVIORAL-BASELINE-CATALOG.json',c)
 delta=[]; queue=[]
 for x in cs:
  cid=x['candidateId']; ls=[z for z in links if z['candidateId']==cid]; ns=[z for z in near if z['candidateId']==cid]
  sem=x['semanticAssessment']['classification']; ora=x['oracleAssessment']['classification']
  typ='INSUFFICIENT_EVIDENCE' if 'INSUFFICIENT_EVIDENCE' in (sem,ora) or not ls else ('POTENTIAL_PARTIAL_OVERLAP' if sem=='PARTIAL_SEMANTIC_OVERLAP' else 'POTENTIAL_NEW_CONDITION')
  units=sorted({z['unitId'] for z in ls if z.get('unitId')})
  delta.append({'candidateId':cid,'application':x['application'],'shortlisted':x['shortlisted'],'semanticAssessment':sem,'oracleAssessment':ora,'provisionalDelta':typ,'baselineUnitIds':units,'candidateBaselineLinks':ls,'nearbyScreenedLinks':ns,'observable':x['oracleAssessment'].get('observable'),'technicalRationale':x.get('technicalRationale'),'reviewerQuestions':x.get('reviewerQuestions',[]),'humanDecision':None,'noveltyStatus':'NOT_VERIFIED','runtimeStatus':'NOT_RUN','limitations':x.get('sourceLimitations',[])+x.get('testabilityRisks',[])})
  queue.append({'candidateId':cid,'application':x['application'],'candidateSummary':x.get('candidateSummary'),'shortlisted':x['shortlisted'],'priorityReviewOrder':x.get('priorityReviewOrder'),'semanticAssessment':sem,'oracleAssessment':ora,'baselineUnitIds':units,'baselineCaseIds':sorted({z['baselineCaseId'] for z in ls}),'overlapAndPossibleDelta':x.get('technicalRationale'),'observable':x['oracleAssessment'].get('observable'),'fixture':x.get('fixtureAssessment'),'negativeControl':x.get('negativeControl'),'testabilityRisks':x.get('testabilityRisks',[]),'reviewerQuestions':x.get('reviewerQuestions',[]),'suggestedDisposition':x.get('suggestedDisposition'),'implementationReadiness':'PENDING_HUMAN_REVIEW','humanDecision':None})
 wr('CANDIDATE-BASELINE-DELTA.json',{'schemaVersion':'1.0.0','task':'T04-G','baselinePin':c['baselinePin'],'interpretation':'Technical only; no novelty decision, approval, RQ2 result, or implementation authorization.','counts':{'candidates':len(delta),'directLinks':len(links),'distinctBaselineCases':len({x['baselineCaseId'] for x in links}),'nearbyLinks':len(near)},'records':delta})
 wr('HUMAN-REVIEW-QUEUE.json',{'schemaVersion':'1.0.0','task':'T04-G','reviewOrderPolicy':'Shortlists first in per-app T04-F priority order, then remaining source order; not a global ranking.','counts':{'candidates':len(queue),'shortlisted':sum(x['shortlisted'] for x in queue)},'records':queue})
 docs={'BASELINE-BEHAVIOR-UNIT-METHOD.md':'# Behavioral Baseline Unit Method\n\nScope: Bludit, Claroline, ExpressCart, Joomla, MantisBT, MediaWiki, PrestaShop at pinned BEWT commit 0501249ff3e9a5ea83a06155cd2971dc36197056; Kanboard is excluded. For each feature preserve Gherkin steps and anchors, map to Java with T04-D, verify pinned blob SHA, and record Java assertions separately. Source text/hash establish provenance, not runtime behavior.\n\nFeature files, Scenario headers, Java suite entries, assertions, and behavioral units differ. Counts: 227 feature files, 204 explicit Scenario headers, 226 feature-to-Java mappings, one feature-only, 228 Java suite entries including two Java-only. The 227 mapped feature records contain 314 Java assertion calls; the two Java-only classes add two more, for 316 assertion-call lines total. These are not unique behavior counts. A unit is a distinct actor/precondition/action/observable/oracle; multiple cases may cover one. Split/merge only with semantic evidence. All records are provisional NEEDS_REVIEW; no denominator is established.\n\nTaxonomy: Normal flow, Negative/validation, Boundary condition, Authorization/role, State/lifecycle, Search/navigation. Keyword labels use pinned Gherkin only; T04-D heuristic tags do not verify behavior. Values are redacted. Runtime image, configuration, fixture/reset, cleanup and Selenium feasibility remain unverified. No official RQ2 denominator or gain is supported.','REVIEW-DECISION-PROTOCOL.md':'# Human Review Decision Protocol\n\nReview independently where practical. Assess real function/version, novelty against linked baseline and search limits, policy-backed observable oracle, fixture/isolation/reset/cleanup, and Selenium feasibility. Rate SUPPORTED/PARTIAL/UNSUPPORTED/UNKNOWN with evidence; unknown is a blocker.\n\nDecisions: ACCEPTED_FOR_IMPLEMENTATION, REVISE, REJECTED, BLOCKED. Record candidate/version, reviewer identity, timezone timestamp, decision, evidence/provenance, rationale, conditions and disagreement. Two reviewers act independently where practical; disagreement stays pending for Team Lead. Never fabricate approval.\n\nCL-GAP-002 requires authoritative access policy. Claroline runtime-image provenance is incomplete. Separate ExpressCart source defects from behavior established by passing baseline tests. EC-GAP-001 is excluded. This package authorizes no implementation.','G1-READINESS-AND-SHORTFALL.md':'# G1 Readiness and Shortfall\n\n27 proposals: Bludit 4, Claroline 4, ExpressCart 3, Joomla 4, MantisBT 4, MediaWiki 4, PrestaShop 4. Shortlist counts 3,3,2,3,3,3,3 (20); five-case targets leave shortfalls 1,1,2,1,1,1,1 (8). No candidates added.\n\nInventory: 227 provisional feature-level records; 204 Scenario headers; 226 feature-to-Java; one feature-only; 228 Java suite entries including two Java-only. The 227 mapped records contain 314 assertions, plus two Java-only assertions, total 316. 46 direct candidate links span 35 baseline cases; 19 nearby links are screening only. T04-F semantic: 19 partial/8 insufficient; oracle: 25 partial/1 source-supported/1 insufficient; insufficient union 9, including CL-GAP-002 once.\n\nStatus PARTIAL_WITH_LIMITATIONS. No decision, novelty validation, runtime result, denominator, RQ2 gain, G1_PASS, ACCEPTED, VALIDATED, or E2E_PASS. Claroline provenance incomplete; CL-GAP-002 needs policy. ExpressCart source defects are distinct from tested behavior. MW-GAP-004 is unresolved duplicate risk. Next: independent review, broader baseline searches, provenance/policy, and later implementation only after human approval.','RESEARCH-LEADS.md':'# Research Leads\n\nNo additional candidate or verified lead is proposed. Eight per-app quota shortfalls remain open; do not fill by inference. New leads require application/version provenance and human novelty/oracle review.'}
 for n,s in docs.items(): (R/n).write_text(s,encoding='utf-8')
 wr('HUMAN-DECISION-TEMPLATE.json',{'candidateId':None,'candidateVersion':None,'reviewerIdentity':None,'reviewedAt':None,'decision':'PENDING_HUMAN_REVIEW','dimensionAssessments':{'functionality':None,'novelty':None,'oracle':None,'fixtureAndReset':None,'seleniumFeasibility':None},'evidenceReferences':[],'rationale':None,'conditions':[],'disagreementReference':None,'provenance':None})
 print(json.dumps({'candidates':len(cs),'links':len(links),'nearby':len(near)}))
if __name__=='__main__': main()
